export const SOUND_IDS=['dragon-wings','enemy-growl','enemy-undead','enemy-beast','enemy-death','enemy-cast','enemy-hurt','enemy-human','lightning','sword','fireball','bow','volley','ice','witch-laugh','witch-pool','witch-kill','troll-aggro','villager-1','villager-2','villager-3','villager-woman','ambient-raven','ambient-wolf','wolf-attack','skeleton-death','wounded','troll-voice','lich-summon','ghost-spawn','ghost-combat','werewolf-aggro','werewolf-hit','dragon-flight','bear-hit'];
// Separate media voices let the witch's victory line finish while Web Audio is suspended.
export function soundEffects({muted=()=>false,makeAudio=url=>new Audio(url)}={}){
 const templates=new Map(SOUND_IDS.map(id=>{const a=makeAudio(new URL('./assets/sfx-'+id+'.mp3',import.meta.url).href);a.preload='none';return [id,a]})),voices=new Set();let trollVoice=false;
 function stop(includeVictory=false){for(const v of [...voices])if(includeVictory||v.id!=='witch-kill'){v.audio.pause();voices.delete(v)}}
 function play(id,{volume=1}={}){if(id==='troll-aggro'){id=trollVoice?'troll-voice':'troll-aggro';trollVoice=!trollVoice}if(muted()||!templates.has(id))return;if(id==='wounded'&&[...voices].some(v=>v.id===id))return;if(id.startsWith('troll-'))for(const v of [...voices])if(v.id.startsWith('troll-')){v.audio.pause();voices.delete(v)}if(id.startsWith('villager-'))for(const v of [...voices])if(v.id.startsWith('villager-')){v.audio.pause();voices.delete(v)}const voiceOnly=['witch-laugh','witch-pool','witch-kill'].includes(id);if(voiceOnly)for(const v of [...voices])if(v.id.startsWith('witch-')){v.audio.pause();voices.delete(v)}
 const matching=[...voices].filter(v=>v.id===id);if(matching.length>=4){matching[0].audio.pause();voices.delete(matching[0])}
 while(voices.size>=14){const oldest=[...voices].find(v=>v.id!=='witch-kill');if(!oldest)break;oldest.audio.pause();voices.delete(oldest)}const audio=templates.get(id).cloneNode(),v={id,audio};audio.volume=id==='dragon-flight'?.24:id==='dragon-wings'?.3:id.startsWith('enemy-')?.45:id.startsWith('ambient-')?.13:id.startsWith('villager-')?.65:id==='wolf-attack'?.5:id.startsWith('witch-')?.9:.75;audio.volume*=Math.max(0,Math.min(1,Number.isFinite(volume)?volume:1));audio.muted=muted();voices.add(v);const clean=()=>voices.delete(v);audio.onended=clean;audio.onerror=clean;try{const result=audio.play();result?.catch(clean)}catch{clean()}}
 return {play,stop,syncMute(){for(const v of voices)v.audio.muted=muted()}};
}
